import { Parser } from './parser';
import { Generators, createPromptInfo, createSampler, PromptInfo } from '../data';
import { ParserError } from '../exceptions';
import { readJsonObject, take, promptList } from './helpers';

const COPYRIGHT = /^Generated by Kus(?:Art|aPics)$/;

/**
 * Parser for images generated by KusArt (formerly KusaPics)
 *
 * KusArt records the prompt, size and style, but no sampler settings.
 */
export class KusArtParser extends Parser {
  public readonly generator = Generators.KUSART;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    if (typeof parameters.Copyright !== 'string' || !COPYRIGHT.test(parameters.Copyright)) {
      throw new ParserError('not a KusArt image');
    }
    const params = readJsonObject(parameters.extra, 'extra');

    const prompt = take(params, 'prompt');
    const negativePrompt = take(params, 'negative_prompt');
    const sampler = createSampler('unknown', {}, {
      prompts: promptList(prompt),
      negativePrompts: promptList(negativePrompt),
    });

    return createPromptInfo(this.generator, [sampler], params, parameters);
  }
}
